static void _parse_eatline(struct vcardparser_state *state)
{
    while (*state->p) {
        /* Handle control characters and break for NUL char */
        HANDLECTRL(state);

        switch (*state->p) {
        case '\n':
            if (state->p[1] == ' ' || state->p[1] == '\t') { /* wrapped line */
                INC(2);
                break;
            }
            /* otherwise it's the end of the line */
            INC(1);
            return;

        default:
            INC(1);
            break;
        }
    }
}

